function* naturals() {
  let n = 1;
  while (true) yield n++;   // infinite, but lazy
}

const it = naturals();
it.next(); // { value: 1, done: false }
it.next(); // { value: 2, done: false }

function* filter(source, keep) {
  for (const x of source) if (keep(x)) yield x;
}

function* take(source, count) {
  if (count <= 0) return;
  let taken = 0;
  for (const x of source) {
    yield x;
    if (++taken >= count) return; // stop pulling from source
  }
}

[...take(filter(naturals(), (n) => n % 2 === 0), 3)]; // [2, 4, 6]
